AssistantMessageToolRequest(name='create', tool_call_id='tooluse_ygjdYSfQtwGq7P0EPZur6i', arguments={'file_text': "/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0a0a0b;
  --bg-secondary: #111114;
  --bg-card: #16161a;
  --bg-card-hover: #1e1e24;
  --border: rgba(255,255,255,0.08);
  --border-accent: rgba(255,255,255,0.15);
  --text-primary: #f0f0f2;
  --text-secondary: #9a9aaa;
  --text-muted: #5a5a6a;
  --accent: #e8c468;
  --accent-dark: #c9a840;
  --accent-red: #e85555;
  --accent-green: #4caf82;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);
  --transition: 0.25s cubic-bezier(0.4,0,0.2,1);
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: #333; border-radius: 3px; }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--accent);
  color: #0a0a0b;
  text-align: center;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.announcement-bar span { margin: 0 16px; opacity: 0.6; }

/* ===== NAVIGATION ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10,10,11,0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
  padding: 0 40px;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 32px;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
  list-style: none;
}
.nav-links a {
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.nav-links a.active { color: var(--text-primary); }
.nav-spacer { flex: 1; }
.nav-search {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 8px 18px;
  width: 240px;
  transition: border-color var(--transition), width var(--transition);
}
.nav-search:focus-within { border-color: var(--border-accent); width: 280px; }
.nav-search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text-primary);
  font-size: 14px;
  width: 100%;
}
.nav-search input::placeholder { color: var(--text-muted); }
.nav-search svg { color: var(--text-muted); flex-shrink: 0; }
.nav-actions { display: flex; align-items: center; gap: 4px; }
.nav-icon-btn {
  position: relative;
  width: 42px; height: 42px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.nav-icon-btn:hover { color: var(--text-primary); background: rgba(255,255,255,0.06); }
.nav-icon-btn .badge {
  position: absolute;
  top: 6px; right: 6px;
  width: 16px; height: 16px;
  background: var(--accent);
  color: #0a0a0b;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg-secondary);
}
.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 60% 40%, rgba(232,196,104,0.08) 0%, transparent 60%),
    radial-gradient(ellipse 50% 80% at 10% 80%, rgba(76,175,130,0.05) 0%, transparent 50%),
    linear-gradient(135deg, #0a0a0b 0%, #111114 50%, #0f0f12 100%);
  z-index: 0;
}
.hero-grid-overlay {
  position: absolute; inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
  z-index: 0;
}
.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 40px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  width: 100%;
}
.hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232,196,104,0.12);
  border: 1px solid rgba(232,196,104,0.25);
  color: var(--accent);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 20px;
  margin-bottom: 28px;
}
.hero-tag::before { content: ''; width: 6px; height: 6px; background: var(--accent); border-radius: 50%; }
.hero-headline {
  font-family: var(--font-serif);
  font-size: clamp(42px, 5vw, 72px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
  color: var(--text-primary);
}
.hero-headline em { color: var(--accent); font-style: italic; }
.hero-sub {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 440px;
  margin-bottom: 40px;
  line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: 10px;
  background: var(--accent);
  color: #0a0a0b;
  font-weight: 700;
  font-size: 15px;
  padding: 14px 28px;
  border-radius: var(--radius-md);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 0 0 0 rgba(232,196,104,0);
}
.btn-primary:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(232,196,104,0.3);
}
.btn-secondary {
  display: inline-flex; align-items: center; gap: 10px;
  background: transparent;
  color: var(--text-primary);
  font-weight: 600;
  font-size: 15px;
  padding: 14px 28px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-accent);
  transition: background var(--transition), border-color var(--transition);
}
.btn-secondary:hover { background: rgba(255,255,255,0.05); border-color: rgba(255,255,255,0.25); }
.hero-stats {
  display: flex;
  gap: 40px;
  margin-top: 56px;
  padding-top: 40px;
  border-top: 1px solid var(--border);
}
.hero-stat-value {
  font-size: 28px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}
.hero-stat-label {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 2px;
}
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-card-stack {
  position: relative;
  width: 400px;
  height: 500px;
}
.hero-product-card {
  position: absolute;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition);
}
.hero-product-card.card-main {
  width: 280px; height: 360px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 3;
}
.hero-product-card.card-back-1 {
  width: 240px; height: 300px;
  top: 30%; left: 60%;
  transform: rotate(8deg);
  z-index: 2;
  opacity: 0.7;
}
.hero-product-card.card-back-2 {
  width: 240px; height: 300px;
  top: 30%; left: 10%;
  transform: rotate(-8deg);
  z-index: 2;
  opacity: 0.7;
}
.hero-product-card:hover { transform: translate(-50%, -52%) scale(1.02); }
.hero-product-img {
  width: 100%; height: 70%;
  object-fit: cover;
  display: flex; align-items: center; justify-content: center;
  font-size: 80px;
}
.hero-product-img.item-1 { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.hero-product-img.item-2 { background: linear-gradient(135deg, #1e1a2e, #2e1a3e); }
.hero-product-img.item-3 { background: linear-gradient(135deg, #1a2e1e, #1a3e2e); }
.hero-product-info {
  padding: 16px;
}
.hero-product-info .product-name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.hero-product-info .product-price { font-size: 16px; font-weight: 700; color: var(--accent); }
.hero-float-badge {
  position: absolute;
  background: var(--accent-red);
  color: white;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 20px;
  z-index: 10;
}
.hero-float-badge.badge-sale { top: 60px; right: 20px; }
.hero-float-badge.badge-new { bottom: 80px; left: 10px; background: var(--accent-green); }

/* ===== SECTION COMMON ===== */
.section { padding: 100px 40px; }
.section-inner { max-width: 1400px; margin: 0 auto; }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 56px;
  gap: 24px;
}
.section-title-group {}
.section-eyebrow {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 10px;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(28px, 3vw, 42px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
}
.section-desc {
  color: var(--text-secondary);
  font-size: 15px;
  margin-top: 8px;
  max-width: 500px;
}
.section-link {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--accent);
  flex-shrink: 0;
  transition: gap var(--transition);
}
.section-link:hover { gap: 12px; }

/* ===== PRODUCT GRID ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  cursor: pointer;
  position: relative;
  group: true;
}
.product-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-color: var(--border-accent);
}
.product-card-img {
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  position: relative;
  overflow: hidden;
}
.product-card-img::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 60%, rgba(0,0,0,0.4));
}
.product-badge {
  position: absolute;
  top: 14px; left: 14px;
  z-index: 2;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
}
.product-badge.new { background: var(--accent-green); color: white; }
.product-badge.sale { background: var(--accent-red); color: white; }
.product-badge.hot { background: var(--accent); color: #0a0a0b; }
.product-wishlist {
  position: absolute;
  top: 12px; right: 12px;
  z-index: 2;
  width: 36px; height: 36px;
  background: rgba(10,10,11,0.7);
  backdrop-filter: blur(8px);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--text-muted);
  opacity: 0;
  transition: opacity var(--transition), color var(--transition), background var(--transition);
}
.product-card:hover .product-wishlist { opacity: 1; }
.product-wishlist:hover { color: var(--accent-red); background: rgba(232,85,85,0.15); }
.product-card-body { padding: 20px; }
.product-category { font-size: 11px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 8px; }
.product-name { font-size: 15px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; line-height: 1.4; }
.product-rating { display: flex; align-items: center; gap: 6px; margin-bottom: 14px; }
.stars { color: var(--accent); font-size: 12px; letter-spacing: 1px; }
.rating-count { font-size: 12px; color: var(--text-muted); }
.product-footer { display: flex; align-items: center; justify-content: space-between; }
.product-price-group { display: flex; align-items: baseline; gap: 8px; }
.product-price { font-size: 20px; font-weight: 800; color: var(--text-primary); }
.product-price-original { font-size: 14px; color: var(--text-muted); text-decoration: line-through; }
.product-price-discount { font-size: 12px; font-weight: 700; color: var(--accent-red); }
.add-to-cart-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  background: var(--accent);
  color: #0a0a0b;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  font-size: 18px;
  font-weight: 700;
}
.add-to-cart-btn:hover {
  background: var(--accent-dark);
  transform: scale(1.1);
  box-shadow: 0 4px 12px rgba(232,196,104,0.4);
}

/* ===== DEALS SECTION ===== */
.deals-section { background: var(--bg-secondary); }
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.deal-card:hover {
  transform: scale(1.01);
  box-shadow: var(--shadow-hover);
  border-color: var(--border-accent);
}
.deal-card.deal-featured {
  grid-row: 1 / 3;
}
.deal-card-bg {
  position: absolute; inset: 0;
  z-index: 0;
  transition: transform 0.6s cubic-bezier(0.4,0,0.2,1);
}
.deal-card:hover .deal-card-bg { transform: scale(1.05); }
.deal-bg-1 {
  background: linear-gradient(135deg, #1a1a2e 0%, #0f0f1e 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 120px;
}
.deal-bg-2 {
  background: linear-gradient(135deg, #2e1a1a 0%, #1e0f0f 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 80px;
}
.deal-bg-3 {
  background: linear-gradient(135deg, #1a2e1a 0%, #0f1e0f 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 80px;
}
.deal-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.2) 60%, transparent 100%);
  z-index: 1;
}
.deal-content {
  position: relative;
  z-index: 2;
  padding: 32px;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 240px;
}
.deal-card.deal-featured .deal-content { min-height: 480px; }
.deal-tag {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent-red);
  color: white;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 20px;
  margin-bottom: 12px;
  align-self: flex-start;
}
.deal-name {
  font-family: var(--font-serif);
  font-size: clamp(20px, 2.5vw, 32px);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 10px;
}
.deal-desc { font-size: 14px; color: rgba(255,255,255,0.7); margin-bottom: 20px; }
.deal-footer { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.deal-price-group { display: flex; align-items: baseline; gap: 8px; }
.deal-price { font-size: 28px; font-weight: 800; color: var(--accent); }
.deal-price-original { font-size: 16px; color: rgba(255,255,255,0.5); text-decoration: line-through; }
.deal-discount-badge {
  background: var(--accent-red);
  color: white;
  font-size: 13px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}
.deal-cta {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--accent);
  color: #0a0a0b;
  font-weight: 700;
  font-size: 14px;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition);
}
.deal-cta:hover { background: var(--accent-dark); transform: scale(1.03); }
.countdown {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
.countdown-unit {
  text-align: center;
}
.countdown-value {
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  font-size: 22px;
  font-weight: 800;
  min-width: 48px;
  display: block;
}
.countdown-label { font-size: 10px; color: rgba(255,255,255,0.5); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.05em; }

/* ===== CATEGORIES STRIP ===== */
.categories-section { padding: 60px 40px; border-bottom: 1px solid var(--border); }
.categories-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: none;
}
.categories-scroll::-webkit-scrollbar { display: none; }
.category-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px 24px;
  cursor: pointer;
  white-space: nowrap;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.category-chip:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-accent);
  transform: translateY(-3px);
}
.category-chip.active {
  border-color: var(--accent);
  background: rgba(232,196,104,0.08);
}
.category-icon { font-size: 24px; }
.category-label { font-size: 14px; font-weight: 600; }
.category-count { font-size: 12px; color: var(--text-muted); }

/* ===== EDITORIAL SECTION ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
}
.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.editorial-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-color: var(--border-accent);
}
.editorial-card.editorial-featured {
  grid-column: 1 / 3;
}
.editorial-img {
  aspect-ratio: 16/9;
  display: flex; align-items: center; justify-content: center;
  font-size: 72px;
  position: relative;
  overflow: hidden;
}
.editorial-card.editorial-featured .editorial-img { aspect-ratio: 21/9; font-size: 100px; }
.editorial-img-1 { background: linear-gradient(135deg, #1a1a2e 0%, #2a1a3e 50%, #1a2e2e 100%); }
.editorial-img-2 { background: linear-gradient(135deg, #2e1a2e 0%, #1a2e1a 100%); }
.editorial-img-3 { background: linear-gradient(135deg, #2e2e1a 0%, #1a1a1a 100%); }
.editorial-body { padding: 24px; }
.editorial-tag {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 10px;
}
.editorial-title {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 10px;
  color: var(--text-primary);
}
.editorial-card.editorial-featured .editorial-title { font-size: 24px; }
.editorial-excerpt { font-size: 14px; color: var(--text-secondary); line-height: 1.65; margin-bottom: 16px; }
.editorial-meta { display: flex; align-items: center; gap: 12px; }
.editorial-avatar {
  width: 32px; height: 32px;
  background: var(--bg-card-hover);
  border: 1px solid var(--border);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px;
}
.editorial-author { font-size: 13px; font-weight: 600; }
.editorial-date { font-size: 12px; color: var(--text-muted); margin-left: auto; }

/* ===== BRANDS SECTION ===== */
.brands-section {
  padding: 60px 40px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.brands-inner { max-width: 1400px; margin: 0 auto; }
.brands-title { text-align: center; font-size: 13px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 40px; }
.brands-row { display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap; }
.brand-item {
  font-family: var(--font-serif);
  font-size: 20px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  transition: color var(--transition);
  cursor: pointer;
}
.brand-item:hover { color: var(--text-primary); }

/* ===== NEWSLETTER ===== */
.newsletter-section {
  padding: 100px 40px;
  background: var(--bg-primary);
}
.newsletter-inner {
  max-width: 1400px;
  margin: 0 auto;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 72px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.newsletter-inner::before {
  content: '';
  position: absolute;
  top: -100px; right: -100px;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(232,196,104,0.07) 0%, transparent 70%);
  pointer-events: none;
}
.newsletter-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent); margin-bottom: 12px; }
.newsletter-title { font-family: var(--font-serif); font-size: 36px; font-weight: 700; line-height: 1.2; margin-bottom: 16px; }
.newsletter-desc { font-size: 15px; color: var(--text-secondary); line-height: 1.7; }
.newsletter-form { display: flex; flex-direction: column; gap: 16px; }
.form-row { display: flex; gap: 12px; }
.form-input {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 15px;
  outline: none;
  transition: border-color var(--transition);
  width: 100%;
}
.form-input:focus { border-color: var(--border-accent); }
.form-input::placeholder { color: var(--text-muted); }
.newsletter-note { font-size: 12px; color: var(--text-muted); }

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 80px 40px 40px;
}
.footer-inner { max-width: 1400px; margin: 0 auto; }
.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 60px;
  margin-bottom: 60px;
}
.footer-brand { }
.footer-logo { font-family: var(--font-serif); font-size: 24px; font-weight: 700; margin-bottom: 16px; }
.footer-logo span { color: var(--accent); }
.footer-tagline { font-size: 14px; color: var(--text-secondary); line-height: 1.7; max-width: 280px; margin-bottom: 28px; }
.footer-social { display: flex; gap: 12px; }
.social-btn {
  width: 40px; height: 40px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary);
  font-size: 16px;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.social-btn:hover { background: rgba(232,196,104,0.1); color: var(--accent); border-color: rgba(232,196,104,0.3); }
.footer-col-title { font-size: 13px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-primary); margin-bottom: 20px; }
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a { font-size: 14px; color: var(--text-secondary); transition: color var(--transition); }
.footer-links a:hover { color: var(--text-primary); }
.footer-bottom {
  padding-top: 32px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.footer-copy { font-size: 13px; color: var(--text-muted); }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 13px; color: var(--text-muted); transition: color var(--transition); }
.footer-legal a:hover { color: var(--text-secondary); }
.footer-payment { display: flex; gap: 8px; align-items: center; }
