}

/* ===== TOAST ===== */
.toast-container {
  position: fixed;
  bottom: 32px; right: 32px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 12px;
  pointer-events: none;
}
.toast {
  background: var(--bg-card);
