  width: 420px;
  height: 100vh;
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 0.35s cubic-bezier(0.4,0,0.2,1);
}
.cart-drawer.open { transform: translateX(0); }
.cart-header {
  padding: 28px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.cart-title { font-family: var(--font-serif); font-size: 22px; font-weight: 700; }
.cart-close {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 18px;
  transition: color var(--transition), background var(--transition);
}
.cart-close:hover { color: var(--text-primary); background: var(--bg-card-hover); }
.cart-items { flex: 1; overflow-y: auto; padding: 24px 28px; display: flex; flex-direction: column; gap: 16px; }
.cart-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px; color: var(--text-muted); }
.cart-empty-icon { font-size: 48px; }
.cart-item {
  display: flex;
  gap: 16px;
  padding: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
.cart-item-img {
  width: 72px; height: 72px;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 32px;
  flex-shrink: 0;
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.cart-item-variant { font-size: 12px; color: var(--text-muted); margin-bottom: 10px; }
.cart-item-footer { display: flex; align-items: center; justify-content: space-between; }
.cart-item-qty {
  display: flex; align-items: center; gap: 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 14px; font-weight: 600;
}
.qty-btn { color: var(--text-muted); font-size: 16px; transition: color var(--transition); }
.qty-btn:hover { color: var(--text-primary); }
.cart-item-price { font-size: 16px; font-weight: 700; color: var(--accent); }
.cart-item-remove { color: var(--text-muted); font-size: 14px; transition: color var(--transition); margin-left: 8px; }
.cart-item-remove:hover { color: var(--accent-red); }
.cart-footer {
  padding: 24px 28px;
  border-top: 1px solid var(--border);
}
.cart-subtotal {
  display: flex; justify-content: space-between;
  font-size: 15px; margin-bottom: 8px;
  color: var(--text-secondary);
}
.cart-total {
  display: flex; justify-content: space-between;
  font-size: 20px; font-weight: 800;
  margin-bottom: 20px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
}
.cart-total-amount { color: var(--accent); }
.checkout-btn {
  width: 100%;
  background: var(--accent);
  color: #0a0a0b;
  font-weight: 700;
  font-size: 16px;
  padding: 16px;
  border-radius: var(--radius-md);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.checkout-btn:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(232,196,104,0.3);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1100px) {
  .hero-inner { grid-template-columns: 1fr; gap: 60px; }
  .hero-visual { display: none; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.editorial-featured { grid-column: 1 / 3; }
}
@media (max-width: 800px) {
  .nav { padding: 0 20px; }
  .nav-links { display: none; }
  .nav-search { display: none; }
  .section { padding: 60px 20px; }
  .categories-section { padding: 40px 20px; }
  .brands-section { padding: 40px 20px; }
  .newsletter-section { padding: 60px 20px; }
  .footer { padding: 60px 20px 32px; }
  .hero-inner { padding: 0 20px; }
  .announcement-bar { font-size: 12px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.deal-featured { grid-row: unset; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.editorial-featured { grid-column: 1; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 40px; padding: 40px 28px; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
  .cart-drawer { width: 100%; }
  .brands-row { gap: 28px; }
}
@media (max-width: 540px) {
  .footer-top { grid-template-columns: 1fr; }
  .hero-stats { gap: 24px; flex-wrap: wrap; }
}
