      <div class="cart-item-img" style="background:${item.bg}">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-variant">${item.category}</div>
        <div class="cart-item-footer">
          <div class="cart-item-qty">
            <button class="qty-btn" onclick="changeQty(${item.id}, -1)">−</button>
            <span>${item.qty}</span>
            <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <span class="cart-item-price">$${(item.price * item.qty).toLocaleString()}</span>
            <button class="cart-item-remove" onclick="removeFromCart(${item.id})" aria-label="Remove">✕</button>
          </div>
        </div>
      </div>
    </div>
  `).join('');
  const subtotal = state.cart.reduce((s, i) => s + i.price * i.qty, 0);
  const shipping = subtotal > 150 ? 0 : 12;
  $('#cart-subtotal-val').textContent = `$${subtotal.toLocaleString()}`;
  $('#cart-shipping-val').textContent = shipping === 0 ? 'Free' : `$${shipping}`;
  $('#cart-total-val').textContent = `$${(subtotal + shipping).toLocaleString()}`;
}

function openCart() {
  state.cartOpen = true;
  $('#cart-drawer').classList.add('open');
  $('#cart-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  state.cartOpen = false;
  $('#cart-drawer').classList.remove('open');
  $('#cart-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== WISHLIST =====

function toggleWishlist(e, productId) {
  e.stopPropagation();
  const btn = $(`#wish-${productId}`);
  if (state.wishlist.has(productId)) {
    state.wishlist.delete(productId);
    if (btn) { btn.style.color = ''; btn.style.background = ''; }
    showToast('💔 Removed from wishlist');
  } else {
    state.wishlist.add(productId);
    if (btn) { btn.style.color = '#e85555'; btn.style.background = 'rgba(232,85,85,0.15)'; btn.style.opacity = '1'; }
    showToast('❤️ Added to wishlist');
  }
}

// ===== PRODUCT TOAST =====
function openProductToast(productId) {
  const product = products.find(p => p.id === productId);
  if (!product) return;
  showToast(`🔍 Viewing ${product.name}`);
}

// ===== TOAST =====

function showToast(message) {
  const container = $('#toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = 'toast';
  const [icon, ...rest] = message.split(' ');
  toast.innerHTML = `
    <span class="toast-icon">${icon}</span>
    <span class="toast-text">${rest.join(' ')}</span>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('removing');
    setTimeout(() => toast.remove(), 300);
  }, 2800);
}

// ===== COUNTDOWN =====

function updateCountdown() {
  let { hours, minutes, seconds } = state.countdown;
  seconds--;
  if (seconds < 0) { seconds = 59; minutes--; }
  if (minutes < 0) { minutes = 59; hours--; }
  if (hours < 0) { hours = 23; minutes = 59; seconds = 59; }
  state.countdown = { hours, minutes, seconds };
  const pad = n => String(n).padStart(2, '0');
  const h = $('#countdown-hours');
  const m = $('#countdown-minutes');
  const s = $('#countdown-seconds');
  if (h) h.textContent = pad(hours);
  if (m) m.textContent = pad(minutes);
  if (s) s.textContent = pad(seconds);
}

