    email.value = '';
  }
}

// ===== CATEGORY FILTER =====
function selectCategory(el) {
  $$('.category-chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  const cat = el.dataset.category;
  let filtered = cat === 'All' ? products : products.filter(p => p.category === cat || cat === 'All');
