  const grid = $('#product-grid');
  if (grid) grid.innerHTML = renderProducts(products);
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  // Render products
  const grid = $('#product-grid');
  if (grid) grid.innerHTML = renderProducts(products);

  // Cart
  const cartBtn = $('#cart-btn');
  const cartClose = $('#cart-close');
  const cartOverlay = $('#cart-overlay');
  if (cartBtn) cartBtn.addEventListener('click', openCart);
  if (cartClose) cartClose.addEventListener('click', closeCart);
  if (cartOverlay) cartOverlay.addEventListener('click', closeCart);

  // Countdown
  setInterval(updateCountdown, 1000);
  updateCountdown();

  // Newsletter
  const form = $('#newsletter-form');
  if (form) form.addEventListener('submit', handleNewsletter);

  // Add to cart from deals
  $$('[data-deal-add]').forEach(btn => {
    btn.addEventListener('click', () => addToCart({ stopPropagation: () => {} }, parseInt(btn.dataset.dealAdd)));
  });

  // Checkout
  const checkoutBtn = $('#checkout-btn');
  if (checkoutBtn) checkoutBtn.addEventListener('click', () => {
    if (state.cart.length === 0) { showToast('🛒 Your cart is empty!'); return; }
    showToast('🎉 Redirecting to checkout...');
  });
});

