        <div class="product-category">${p.category}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-rating">
          <span class="stars">${renderStars(p.stars)}</span>
          <span class="rating-count">(${p.reviews.toLocaleString()})</span>
        </div>
        <div class="product-footer">
          <div class="product-price-group">
            <span class="product-price">$${p.price}</span>
            ${p.originalPrice ? `<span class="product-price-original">$${p.originalPrice}</span>` : ''}
            ${p.discount ? `<span class="product-price-discount">${p.discount}</span>` : ''}
          </div>
          <button class="add-to-cart-btn" onclick="addToCart(event, ${p.id})" aria-label="Add to cart">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
              <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
              <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>
            </svg>
