}

// ===== CART =====

function addToCart(e, productId) {
  e.stopPropagation();
  const product = products.find(p => p.id === productId);
  if (!product) return;
  const existing = state.cart.find(i => i.id === productId);
  if (existing) {
    existing.qty++;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  updateCartBadge();
  renderCart();
  showToast(`${product.emoji} ${product.name} added to cart`);
}

function removeFromCart(productId) {
  state.cart = state.cart.filter(i => i.id !== productId);
  updateCartBadge();
  renderCart();
}

function changeQty(productId, delta) {
  const item = state.cart.find(i => i.id === productId);
  if (!item) return;
  item.qty = Math.max(1, item.qty + delta);
  updateCartBadge();
  renderCart();
}

function updateCartBadge() {
  const total = state.cart.reduce((s, i) => s + i.qty, 0);
  const badge = $('#cart-badge');
  if (badge) {
    badge.textContent = total;
    badge.style.display = total > 0 ? 'flex' : 'none';
  }
}

function renderCart() {
  const container = $('#cart-items');
  if (!container) return;
  if (state.cart.length === 0) {
    container.innerHTML = `
      <div class="cart-empty">
        <div class="cart-empty-icon">🛒</div>
        <div style="font-size:16px;font-weight:600;color:var(--text-secondary)">Your cart is empty</div>
        <div style="font-size:14px">Add some items to get started</div>
      </div>`;
    $('#cart-subtotal-val').textContent = '$0.00';
    $('#cart-total-val').textContent = '$0.00';
    return;
  }
  container.innerHTML = state.cart.map(item => `
    <div class="cart-item">
      <div class="cart-item-img" style="background:${item.bg}">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-variant">${item.category}</div>
        <div class="cart-item-footer">
          <div class="cart-item-qty">
            <button class="qty-btn" onclick="changeQty(${item.id}, -1)">−</button>
            <span>${item.qty}</span>
            <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <span class="cart-item-price">$${(item.price * item.qty).toLocaleString()}</span>
            <button class="cart-item-remove" onclick="removeFromCart(${item.id})" aria-label="Remove">✕</button>
          </div>
        </div>
      </div>
    </div>
  `).join('');
  const subtotal = state.cart.reduce((s, i) => s + i.price * i.qty, 0);
  const shipping = subtotal > 150 ? 0 : 12;
  $('#cart-subtotal-val').textContent = `$${subtotal.toLocaleString()}`;
  $('#cart-shipping-val').textContent = shipping === 0 ? 'Free' : `$${shipping}`;
  $('#cart-total-val').textContent = `$${(subtotal + shipping).toLocaleString()}`;
}

function openCart() {
  state.cartOpen = true;
  $('#cart-drawer').classList.add('open');
  $('#cart-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  state.cartOpen = false;
  $('#cart-drawer').classList.remove('open');
  $('#cart-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== WISHLIST =====

function toggleWishlist(e, productId) {
  e.stopPropagation();
  const btn = $(`#wish-${productId}`);
  if (state.wishlist.has(productId)) {
    state.wishlist.delete(productId);
    if (btn) { btn.style.color = ''; btn.style.background = ''; }
    showToast('💔 Removed from wishlist');
  } else {
    state.wishlist.add(productId);
    if (btn) { btn.style.color = '#e85555'; btn.style.background = 'rgba(232,85,85,0.15)'; btn.style.opacity = '1'; }
    showToast('❤️ Added to wishlist');
  }
}

// ===== PRODUCT TOAST =====
function openProductToast(productId) {
  const product = products.find(p => p.id === productId);
  if (!product) return;
  showToast(`🔍 Viewing ${product.name}`);
}

// ===== TOAST =====

function showToast(message) {
  const container = $('#toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = 'toast';
  const [icon, ...rest] = message.split(' ');
  toast.innerHTML = `
    <span class="toast-icon">${icon}</span>
    <span class="toast-text">${rest.join(' ')}</span>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('removing');
    setTimeout(() => toast.remove(), 300);
  }, 2800);
}

// ===== COUNTDOWN =====

function updateCountdown() {
  let { hours, minutes, seconds } = state.countdown;
  seconds--;
  if (seconds < 0) { seconds = 59; minutes--; }
  if (minutes < 0) { minutes = 59; hours--; }
  if (hours < 0) { hours = 23; minutes = 59; seconds = 59; }
  state.countdown = { hours, minutes, seconds };
  const pad = n => String(n).padStart(2, '0');
  const h = $('#countdown-hours');
  const m = $('#countdown-minutes');
  const s = $('#countdown-seconds');
  if (h) h.textContent = pad(hours);
  if (m) m.textContent = pad(minutes);
  if (s) s.textContent = pad(seconds);
}

// ===== NEWSLETTER =====
function handleNewsletter(e) {
  e.preventDefault();
  const email = e.target.querySelector('input[type=email]');
  if (email && email.value) {
    showToast('📬 You\'re subscribed! Check your inbox.');
    email.value = '';
  }
}

// ===== CATEGORY FILTER =====
function selectCategory(el) {
  $$('.category-chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  const cat = el.dataset.category;
  let filtered = cat === 'All' ? products : products.filter(p => p.category === cat || cat === 'All');
  // For demo, just show all
  const grid = $('#product-grid');
  if (grid) grid.innerHTML = renderProducts(products);
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  // Render products
  const grid = $('#product-grid');
  if (grid) grid.innerHTML = renderProducts(products);

  // Cart
  const cartBtn = $('#cart-btn');
  const cartClose = $('#cart-close');
  const cartOverlay = $('#cart-overlay');
  if (cartBtn) cartBtn.addEventListener('click', openCart);
  if (cartClose) cartClose.addEventListener('click', closeCart);
  if (cartOverlay) cartOverlay.addEventListener('click', closeCart);

  // Countdown
  setInterval(updateCountdown, 1000);
  updateCountdown();

  // Newsletter
  const form = $('#newsletter-form');
  if (form) form.addEventListener('submit', handleNewsletter);

  // Add to cart from deals
  $$('[data-deal-add]').forEach(btn => {
    btn.addEventListener('click', () => addToCart({ stopPropagation: () => {} }, parseInt(btn.dataset.dealAdd)));
  });

  // Checkout
  const checkoutBtn = $('#checkout-btn');
  if (checkoutBtn) checkoutBtn.addEventListener('click', () => {
    if (state.cart.length === 0) { showToast('🛒 Your cart is empty!'); return; }
    showToast('🎉 Redirecting to checkout...');
  });
});
